/**
 * The image library of the Images tab: ready-made images a person adds to
 * the draft as if they had dropped the files. Three collections: status
 * symbols (flat filled), GRC object icons (40 px, three styles) and button
 * icons (Phosphor, two weights). The data is generated by
 * scripts/generate-image-library.mjs and loaded only when the library is
 * opened (its own chunk). Every item carries search keywords; searchLibrary
 * finds items by the start of their words. Colours are set with the SVG colour swap of
 * svg-colors.ts; nothing here writes to BMP.
 *
 * Pure apart from the dynamic import: no chrome.*, DOM only through DOMParser.
 */
import { hexToRgb, normalizeHex, rgbToHex, rgbToHsl } from './color-math';
import { adjustSvgText } from './image-process';
import { CURRENT_COLOR, svgColorsOfText } from './svg-colors';

export type CollectionId = 'status' | 'grc' | 'buttons';

export interface LibraryVariant { id: string; label: string }

export interface LibraryItem {
  /** Unique in the library: `<collection>:<name>`. */
  key: string;
  collection: CollectionId;
  group: string;
  /** What the tile says ("Green check", "Warning triangle", "plus-circle"). */
  label: string;
  /** The number of a GRC metaphor (R1, C2 …). */
  code?: string;
  /** Search words beyond the name: meaning, colour, shape, German words (status symbols and
   *  GRC icons, written by hand), or Phosphor's tags and categories (button icons). */
  keywords: readonly string[];
  /** The words of the name (label, number, file stem), folded for the search. */
  nameWords: readonly string[];
  /** The words of the group, the collection and the keywords, folded for the search. */
  otherWords: readonly string[];
  /** SVG text per variant id. */
  svg: Readonly<Record<string, string>>;
  /** File name per variant id: the draft proposes the ID from it. */
  fileName: Readonly<Record<string, string>>;
}

export interface LibraryCollection {
  id: CollectionId;
  name: string;
  /** What the variant switch is called; absent with one variant. */
  variantLabel?: string;
  variants: readonly LibraryVariant[];
  groups: ReadonlyArray<{ name: string; items: readonly LibraryItem[] }>;
  /** The description the image gets in BMP ('' for none). */
  description: string;
}

export interface Library { collections: readonly LibraryCollection[] }

/** The licence note a Phosphor icon carries in BMP. The owner's own drawings carry none. */
export const PHOSPHOR_NOTE = 'Phosphor Icons (MIT License), phosphoricons.com';

const words = (s: string) => s.replace(/[_-]+/g, ' ').trim();
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

/** "status_dot_green_check" in Status dots → "Green check"; "harvey_25" → "25%". */
export function statusLabel(stem: string): string {
  const harvey = /^harvey_(\d+)$/.exec(stem);
  if (harvey) return `${harvey[1]}%`;
  const rest = stem.replace(/^status_(?:dot|square)_/, '').replace(/^(?:control|progress|trend|risk|approval|traffic)_/, '');
  return cap(words(rest));
}

const PHOSPHOR_OPEN = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="24" height="24" fill="currentColor">';

type Words = readonly string[];
type StatusData = ReadonlyArray<readonly [string, ReadonlyArray<readonly [string, string, Words?]>]>;
type GrcData = ReadonlyArray<readonly [string, ReadonlyArray<readonly [string, string, string, string, string, Words?]>]>;
type ButtonData = ReadonlyArray<readonly [string, ReadonlyArray<readonly [string, string, string, Words?]>]>;

export const COLLECTION_NAMES: Readonly<Record<CollectionId, string>> = { status: 'Status symbols', grc: 'GRC object icons', buttons: 'Button icons' };

/** Text as the search compares it: lower case, no accents ("grün" gives "grun"). */
export function fold(text: string): string {
  return text.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/ß/g, 'ss').toLowerCase();
}

/** The search words of a text: folded, split at anything that is not a letter or digit.
 *  A German umlaut also gives its spelled-out form ("grün" gives "grun" and "gruen"). */
export function searchWords(text: string): string[] {
  const out = new Set<string>();
  for (const w of text.toLowerCase().split(/[^\p{L}\p{N}]+/u)) {
    if (!w) continue;
    out.add(fold(w));
    if (/[äöü]/.test(w)) out.add(fold(w.replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')));
  }
  return [...out];
}

function wordsOf(name: readonly string[], other: readonly string[]): { nameWords: string[]; otherWords: string[] } {
  const nameWords = [...new Set(name.flatMap(searchWords))];
  return { nameWords, otherWords: [...new Set(other.flatMap(searchWords))].filter(w => !nameWords.includes(w)) };
}

export const GRC_STYLES: readonly LibraryVariant[] = [{ id: 'line', label: 'Line' }, { id: 'twotone', label: 'Two-tone' }, { id: 'tile', label: 'Tile' }];
export const BUTTON_WEIGHTS: readonly LibraryVariant[] = [{ id: 'regular', label: 'Regular' }, { id: 'fill', label: 'Fill' }];

/** The library from its data modules. */
export function buildLibrary(status: StatusData, grc: GrcData, buttons: ButtonData): Library {
  const statusGroups = status.map(([group, items]) => ({
    name: group,
    items: items.map(([stem, svg, keywords = []]): LibraryItem => ({
      key: `status:${stem}`, collection: 'status', group, label: statusLabel(stem), keywords,
      ...wordsOf([statusLabel(stem), words(stem)], [group, COLLECTION_NAMES.status, ...keywords]),
      svg: { flat: svg }, fileName: { flat: `${stem}.svg` },
    })),
  }));
  const grcGroups = grc.map(([group, items]) => ({
    name: group,
    items: items.map(([code, slug, line, twotone, tile, keywords = []]): LibraryItem => {
      const stem = `${group.toLowerCase()}_${slug.replace(/-/g, '_')}`;
      return {
        key: `grc:${code}`, collection: 'grc', group, label: cap(words(slug)), code, keywords,
        ...wordsOf([code, words(slug)], [group, COLLECTION_NAMES.grc, ...keywords]),
        svg: { line, twotone, tile },
        fileName: { line: `${stem}_line.svg`, twotone: `${stem}_twotone.svg`, tile: `${stem}_tile.svg` },
      };
    }),
  }));
  const buttonGroups = buttons.map(([group, items]) => ({
    name: group,
    items: items.map(([name, regular, fill, keywords = []]): LibraryItem => ({
      key: `buttons:${name}`, collection: 'buttons', group, label: name, keywords,
      ...wordsOf([words(name)], [group, COLLECTION_NAMES.buttons, ...keywords]),
      svg: { regular: `${PHOSPHOR_OPEN}${regular}</svg>`, fill: `${PHOSPHOR_OPEN}${fill}</svg>` },
      fileName: { regular: `${name}.svg`, fill: `${name}-fill.svg` },
    })),
  }));
  return {
    collections: [
      { id: 'status', name: COLLECTION_NAMES.status, variants: [{ id: 'flat', label: 'Flat' }], groups: statusGroups, description: '' },
      { id: 'grc', name: COLLECTION_NAMES.grc, variantLabel: 'Style', variants: GRC_STYLES, groups: grcGroups, description: '' },
      { id: 'buttons', name: COLLECTION_NAMES.buttons, variantLabel: 'Weight', variants: BUTTON_WEIGHTS, groups: buttonGroups, description: PHOSPHOR_NOTE },
    ],
  };
}

let loading: Promise<Library> | null = null;

/** The library, read once: the data is its own chunk, loaded on the first call. */
export function loadLibrary(): Promise<Library> {
  loading ??= Promise.all([
    import('./library-data/status-symbols'), import('./library-data/grc-object-icons'), import('./library-data/button-icons'),
  ]).then(([s, g, b]) => buildLibrary(s.STATUS_SYMBOLS, g.GRC_OBJECT_ICONS, b.BUTTON_ICONS));
  loading.catch(() => { loading = null; });
  return loading;
}

export function itemsOf(c: LibraryCollection): LibraryItem[] {
  return c.groups.flatMap(g => g.items);
}

/** How well an item answers the words of a query: 0 when every word starts a word of its
 *  name, higher the more words only its group, collection or keywords answer; null for no match. */
export function matchRank(item: LibraryItem, terms: readonly string[]): number | null {
  let rank = 0;
  for (const t of terms) {
    if (item.nameWords.some(w => w.startsWith(t))) continue;
    if (!item.otherWords.some(w => w.startsWith(t))) return null;
    rank += 1;
  }
  return rank;
}

/** The words of a query as the search uses them (folded, split like the items' words). */
export function queryTerms(query: string): string[] {
  return query.toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(fold);
}

/**
 * The library's answer to a query: the items where every word of the query starts a
 * word of the name, group, collection or keywords (case and accents do not matter:
 * "grun" finds "grün"). Name matches come first, then items found through their
 * keywords; otherwise the library's order. No query: nothing.
 */
export function searchLibrary(items: readonly LibraryItem[], query: string): LibraryItem[] {
  const terms = queryTerms(query);
  if (!terms.length) return [];
  return items.map((item, i) => ({ item, i, rank: matchRank(item, terms) }))
    .filter((x): x is { item: LibraryItem; i: number; rank: number } => x.rank !== null)
    .sort((a, b) => a.rank - b.rank || a.i - b.i)
    .map(x => x.item);
}

/** The items of one collection that answer `query` (every item for an empty query). */
export function searchItems(c: LibraryCollection, query: string): LibraryItem[] {
  return queryTerms(query).length ? searchLibrary(itemsOf(c), query) : itemsOf(c);
}

/** Every item of the library, collection by collection. */
export function allItems(lib: Library): LibraryItem[] {
  return lib.collections.flatMap(itemsOf);
}

// ── colours ─────────────────────────────────────────────────────────

export interface LibraryColor {
  /** `original` keeps the file's colours; `one` paints the drawing in `hex`
   *  (white parts stay white, light tints become a tint of `hex`); `swap`
   *  replaces the colours named in `map`. */
  mode: 'original' | 'one' | 'swap';
  hex: string;
  map: Readonly<Record<string, string>>;
}

export const WHITE = '#FFFFFF';

/** A light tint of a colour (12 % of it on white): the soft fill of a two-tone icon or a tile. */
export function tintOf(hex: string): string {
  const { r, g, b } = hexToRgb(hex);
  const mix = (v: number) => Math.round(255 * 0.88 + v * 0.12);
  return rgbToHex({ r: mix(r), g: mix(g), b: mix(b) });
}

/** Is a colour a light tint (not white): a soft fill, not the drawing's ink? */
export function isTint(hex: string): boolean {
  const n = normalizeHex(hex);
  if (!n || n === WHITE) return false;
  return rgbToHsl(hexToRgb(n)).l >= 0.84;
}

/** The colours of an SVG text as the swap knows them (`#RRGGBB` or currentColor). */
export function colorsOf(svg: string): string[] {
  return svgColorsOfText(svg).map(c => c.key);
}

/** The colour map the choice gives for an image with these colours. */
export function colorMapFor(colors: readonly string[], c: LibraryColor): Record<string, string> {
  if (c.mode === 'swap') {
    const map: Record<string, string> = {};
    for (const k of colors) if (c.map[k]) map[k] = c.map[k];
    return map;
  }
  if (c.mode !== 'one') return {};
  const hex = normalizeHex(c.hex) ?? c.hex;
  const map: Record<string, string> = {};
  for (const k of colors) {
    if (k === WHITE) continue;
    map[k] = k !== CURRENT_COLOR && isTint(k) ? tintOf(hex) : hex;
  }
  return map;
}

/** The SVG as it is added: the colours set, cleaned, with its width and height. */
export function coloredSvg(svg: string, c: LibraryColor): string {
  const map = colorMapFor(colorsOf(svg), c);
  return adjustSvgText(svg, { color: { mode: 'swap', hex: c.hex, map }, size: 'keep', padding: 0, format: 'svg' }).svg;
}

/** The colour a library image's proposed ID ends with: the one colour as six lower-case
 *  hex digits ("ffffff"); '' with Original or Swap colors. */
export function colorSuffix(c: Pick<LibraryColor, 'mode' | 'hex'>): string {
  if (c.mode !== 'one') return '';
  return (normalizeHex(c.hex) ?? '').slice(1).toLowerCase();
}

/** The files to add to the draft, in the order given, with the description each gets in BMP.
 *  They are marked as library images: their IDs start with `icon_` where the folder gives no
 *  prefix, and end with the one colour when one is set. */
export function libraryFiles(
  picks: ReadonlyArray<{ item: LibraryItem; variant: string; description: string }>, c: LibraryColor,
): Array<{ name: string; bytes: Uint8Array; description?: string; library: { hex: string } }> {
  const enc = new TextEncoder();
  const hex = colorSuffix(c);
  return picks.map(({ item, variant, description }) => {
    const v = item.svg[variant] !== undefined ? variant : Object.keys(item.svg)[0];
    return { name: item.fileName[v], bytes: enc.encode(coloredSvg(item.svg[v], c)), ...(description ? { description } : {}), library: { hex } };
  });
}
